from docx import Document
p='/mnt/data/GMRI_Biographical_Record_Robert_Grizz_Hanson_v1.1(20261028-023904).docx'
d=Document(p)
print('sections', len(d.sections), 'paragraphs',len(d.paragraphs), 'tables',len(d.tables))
for i,x in enumerate(d.paragraphs):
 if ('disaster' in x.text.lower() or 'scenario' in x.text.lower() or '2007' in x.text.lower() or 'Source Notes' in x.text or 'Prepared' in x.text or 'Record purpose' in x.text or 'firsthand' in x.text.lower()):
  print(i,repr(x.text[:700]), 'style=',x.style.name, 'runs=',[(r.text[:40],r.bold,r.italic) for r in x.runs[:6]])
for ti,t in enumerate(d.tables):
 print('table',ti)
 for ri,row in enumerate(t.rows): print(ri,[c.text[:150] for c in row.cells])
